.selected-tag{display:inline-block;position:relative;background-color:#dee2e6;border:1px solid rgba(60,60,60,.26);border-radius:4px;color:#333;line-height:1.4;margin:.25em .25em 0 0;padding:0 .25em}.selected-tag.draggable{cursor:pointer}.selected-tag.draggable .text{-webkit-touch-callout:none;-webkit-user-select:none;-khtml-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none}.selected-tag:hover{background-color:#cfd5db;color:#262626}.selected-tag:hover .selected-relevance{background-color:#0cb6d8}.selected-tag .selected-relevance{position:absolute;left:0;top:0;height:100%;background-color:#0dcaf0}.selected-tag .selected-relevance.isDragging{background-color:#fd7e14}.selected-tag .text{display:inline;position:relative;user-select:none}