.pdfPreview .previewContainer{position:relative;overflow:hidden;cursor:pointer}.pdfPreview .previous,.pdfPreview .next{position:absolute;background-color:rgba(255,255,255,.5);color:#000;font-size:2em;top:50%;cursor:pointer}.pdfPreview .previous:hover,.pdfPreview .next:hover{background-color:#fff}.pdfPreview .previous{left:.25em}.pdfPreview .next{right:.25em}.pdfPreview .label{position:absolute;bottom:0;left:0;right:0;text-align:center;padding:.25em .5em .25em .5em;background-image:linear-gradient(rgba(255, 255, 255, 0.85), #ffffff)}.pdfPreview .limitedPreview{font-size:smaller}.pdfPreview .pdfPreviewImage{min-height:5em;min-width:100%}