.bibleverse-wrapper{position:relative;margin-bottom:.25rem;margin-right:.25rem}.bibleverse-wrapper.mini{margin-bottom:.125rem;margin-top:.125rem;margin-left:0;margin-right:.125em}.bibleverse-wrapper.mini .icon{height:.7rem;width:.7rem;margin-right:.05rem}.bibleverse-wrapper.mini .sb-bibleverse{font-size:.7em;padding:.125rem .25rem}.bibleverse-wrapper>.sb-bibleverse{border:none;background-color:#6c757d;cursor:pointer}.bibleverse-wrapper>.sb-bibleverse:hover{background-color:#60686f}.bibleverse-wrapper>.sb-bibleverse:hover .sb-progress-bar{background-color:#3dd5f3}.bibleverse-wrapper>.sb-bibleverse .sb-progress-bar{position:absolute;left:0;top:0;height:100%;border-radius:.2rem;background-color:#0dcaf0}.bibleverse-wrapper>.sb-bibleverse .sb-progress-bar.isDragging{background-color:#fd7e14}.bibleverse-wrapper>.sb-bibleverse.highlighted .sb-progress-bar{background-color:#0dcaf0}.bibleverse-wrapper>.sb-bibleverse .text{color:#fff;position:relative;text-shadow:.05em .05em .2em #60686f}.bibleverse-wrapper>.sb-bibleverse .icon{position:relative;height:1rem;margin-right:.1rem;top:-0.1rem}.bibleverse-wrapper>.sb-bibleverse .icon path{fill:#000}.bibleverse-wrapper>.sb-bibleverse .delete{position:relative;color:#f5f5f5;padding-left:.25em;font-weight:bold;cursor:pointer}.bibleverse-wrapper>.sb-bibleverse .delete:hover{color:#000}