.zoomImageModal .previous,.zoomImageModal .next{position:absolute;color:#000;font-size:2em;height:100%;top:0;cursor:pointer;display:flex;justify-content:center;flex-direction:column;padding:0;overflow:hidden}.zoomImageModal .previous svg,.zoomImageModal .next svg{height:1em;width:1em}.zoomImageModal .previous .circle,.zoomImageModal .next .circle{width:2em;height:2em;background-color:#fff;text-align:center;box-shadow:0 0 1em .5em rgba(0,0,0,.1)}.zoomImageModal .previous:hover .circle,.zoomImageModal .next:hover .circle{box-shadow:0 0 1em .5em rgba(0,0,0,.2)}.zoomImageModal .previous{left:0}.zoomImageModal .previous .circle{margin-right:1em;border-top-right-radius:50%;border-bottom-right-radius:50%}.zoomImageModal .next{right:0}.zoomImageModal .next .circle{margin-left:1em;border-top-left-radius:50%;border-bottom-left-radius:50%}.zoomImageModal .previous:hover{background-image:linear-gradient(to right, #b8b8b8, rgba(210, 210, 210, 0.05))}.zoomImageModal .next:hover{background-image:linear-gradient(to left, #b8b8b8, rgba(210, 210, 210, 0.05))}.zoomImageModal .modal-header{justify-content:center}